//! Pegged Reply, Reaction and Edit sends from go-foks main clients (bf9ace5),
//! using the rtSend arguments in `foks-main/realtime` generated by
//! `tools/foks-main-oracle`.
use super::*;

/// Fixture order; each message names the previous one as its predecessor.
const PEGGED: [(&str, RtMessageType); 5] = [
    ("reply", RtMessageType::Reply),
    ("reactji", RtMessageType::Reaction),
    ("edit", RtMessageType::Edit),
    ("delete", RtMessageType::Edit),
    // Reaction metadata over an Edit arm: the server cannot see the arm, so
    // it stores this as go-foks main does and readers refuse it.
    ("mismatch", RtMessageType::Reaction),
];

fn fixture(name: &str) -> Vec<u8> {
    std::fs::read(format!(
        "{}/../foks-snowpack/tests/fixtures/foks-main/realtime/{name}",
        env!("CARGO_MANIFEST_DIR")
    ))
    .unwrap()
}

fn go_send(name: &str) -> RtSendArgument {
    RtSendArgument {
        send: RtSend::decode(&fixture(&format!("send-pegged-{name}.snowp"))).unwrap(),
    }
}

/// Microsecond clock value at which the Rust server assigns the fixture's
/// insert time (milliseconds) to the message at `index`.
fn at(index: usize) -> u64 {
    (1_700_000_000_200 + index as u64) * 1000
}

/// The fixtures' sender, channel and target message installed on the Rust
/// fixture's team.
fn go_channel() -> (Fixture, RealtimeActor) {
    let mut f = Fixture::new();
    // The fixture times are real clock values.
    f.owner.certificate_expires_at = u64::MAX;
    f.member.certificate_expires_at = u64::MAX;
    let mut uid = vec![0; 33];
    uid[0] = ENTITY_USER;
    uid[1] = 7;
    let go = RealtimeActor {
        host: f.owner.host.clone(),
        uid,
        credential: id(ENTITY_DEVICE, 9),
        certificate_expires_at: u64::MAX,
    };
    let team = f.create.metadata.team.entity().as_bytes().to_vec();
    f.db.connection
        .execute(
            "INSERT INTO names(normalized_name,reservation_sequence,uid) VALUES (?1,1,?1)",
            params![go.uid],
        )
        .unwrap();
    f.db.connection.execute("INSERT INTO users(uid,normalized_name,username_utf8,username_sequence,username_commitment_key,created_at) VALUES (?1,?1,?1,1,zeroblob(16),0)",params![go.uid]).unwrap();
    f.db.connection.execute("INSERT INTO devices(device_id,uid,active,role_type,visibility,hepk_fingerprint,self_token,exact_hepk,exact_name) VALUES (?1,?2,1,3,0,zeroblob(32),zeroblob(17),X'00',X'00')",params![go.credential,go.uid]).unwrap();
    f.db.connection.execute("INSERT INTO team_members(team_id,party_id,source_role_type,source_visibility,role_type,visibility,generation,verify_key,hepk_fingerprint) VALUES (?1,?2,3,0,1,0,1,zeroblob(33),zeroblob(32))",params![team,go.uid]).unwrap();
    let mut chid = [0; 16];
    chid[0] = 0x81;
    chid[15] = 0x22;
    f.create.metadata.id = RtChannelId(chid);
    f.db.rt_create_channel(&f.owner, &f.create, 1_000_000)
        .unwrap();
    let mut target = f.send(0x33);
    target.send.metadata.id = RtMessageId([0; 16]);
    target.send.metadata.id.0[0] = 0x33;
    assert_eq!(
        f.db.rt_send(&go, &target, at(0) - 1000)
            .unwrap()
            .value
            .sequence,
        1
    );
    (f, go)
}

fn last_kind(f: &Fixture) -> RtMessageType {
    let list = RtListChannelsArgument {
        team: f.create.metadata.team.clone(),
        app: RtAppId::Chat,
        last: 0,
    };
    f.reader()
        .snapshot()
        .unwrap()
        .rt_list_channels(&f.member, &list, at(9))
        .unwrap()
        .channels[0]
        .last_message
        .as_ref()
        .unwrap()
        .kind
}

#[test]
fn go_main_pegged_sends_are_stored_and_reserved_byte_for_byte() {
    let (mut f, go) = go_channel();
    for (index, (name, kind)) in PEGGED.iter().enumerate() {
        let arg = go_send(name);
        assert_eq!(arg.send.metadata.kind, *kind);
        assert_eq!(arg.send.expected_previous_sequence, 0);
        let commit = f.db.rt_send(&go, &arg, at(index)).unwrap();
        assert_eq!(commit.value.sequence, index as u64 + 2);
        assert_eq!(commit.value.insert_time, at(index) / 1000);
        assert!(!commit.value.was_replay);
        // Fan-out is the same as for Basic: every member is woken.
        assert_eq!(commit.wake.len(), 3);
        assert_eq!(last_kind(&f), *kind);
    }
    // History re-serves exactly the RTMsg a go-foks main server returns, to
    // any reader.
    let reader = f.reader();
    let snapshot = reader.snapshot().unwrap();
    for actor in [&f.member, &f.owner, &go] {
        let recent = snapshot
            .rt_recents(
                actor,
                &RtRecentsArgument {
                    channel: f.create.metadata.id,
                    stop_at: 0,
                    limit: 10,
                },
                at(9),
            )
            .unwrap();
        assert_eq!(recent.messages.len(), 6);
        for (index, (name, _)) in PEGGED.iter().enumerate() {
            let message = &recent.messages[PEGGED.len() - 1 - index];
            assert_eq!(
                message.encoded().unwrap(),
                fixture(&format!("pegged-{name}.snowp")),
                "{name}"
            );
        }
        let page = snapshot
            .rt_thread(
                actor,
                &RtGetThreadArgument {
                    query: RtThreadQuery {
                        channel: f.create.metadata.id,
                        ranges: vec![RtThreadRange { start: 2, end: 6 }],
                        sequences: vec![3],
                    },
                },
                at(9),
            )
            .unwrap();
        assert_eq!(page.ranges[0].messages.len(), 5);
        assert_eq!(
            page.sequences[0].encoded().unwrap(),
            fixture("pegged-reactji.snowp")
        );
    }
}

#[test]
fn pegged_sends_follow_the_replay_and_ordering_rules() {
    let (mut f, go) = go_channel();
    let reply = go_send("reply");
    let delivered = f.db.rt_send(&go, &reply, at(0)).unwrap().value;
    // A lost-ack retry is a replay, also when its precondition names the
    // head before its own delivery.
    let mut retry = reply.clone();
    for expected in [0, 1] {
        retry.send.expected_previous_sequence = expected;
        let replay = f.db.rt_send(&go, &retry, at(5)).unwrap();
        assert!(replay.value.was_replay);
        assert!(replay.wake.is_empty());
        assert_eq!(replay.value.sequence, delivered.sequence);
        assert_eq!(replay.value.insert_time, delivered.insert_time);
    }
    // The same message ID with another kind, ciphertext or sender is a
    // replay mismatch.
    let mut kind = reply.clone();
    kind.send.metadata.kind = RtMessageType::Edit;
    let mut ciphertext = reply.clone();
    let RtMessageWrapper::Encrypted(boxed) = &mut ciphertext.send.wrapper else {
        panic!("encrypted")
    };
    boxed.ciphertext.0[0] ^= 1;
    for changed in [&kind, &ciphertext] {
        assert!(matches!(
            f.db.rt_send(&go, changed, at(5)),
            Err(Error::OperationConflict)
        ));
    }
    assert!(matches!(
        f.db.rt_send(&f.member, &reply, at(5)),
        Err(Error::OperationConflict)
    ));
    // A fresh pegged send with a stale precondition or a wrong predecessor
    // is refused like a Basic one.
    let mut reactji = go_send("reactji");
    reactji.send.expected_previous_sequence = 1;
    assert!(matches!(
        f.db.rt_send(&go, &reactji, at(1)),
        Err(Error::RtMessageOrder)
    ));
    reactji.send.expected_previous_sequence = 0;
    let mut wrong = reactji.clone();
    wrong.send.metadata.previous_id.0[1] = 1;
    assert!(matches!(
        f.db.rt_send(&go, &wrong, at(1)),
        Err(Error::RtMessageOrder)
    ));
    reactji.send.expected_previous_sequence = 2;
    assert_eq!(
        f.db.rt_send(&go, &reactji, at(1)).unwrap().value.sequence,
        3
    );
    // A Basic send may name a pegged message as its predecessor.
    let mut basic = f.send(9);
    basic.send.metadata.previous_id = reactji.send.metadata.id;
    basic.send.metadata.previous_sequence = 3;
    basic.send.expected_previous_sequence = 3;
    assert_eq!(
        f.db.rt_send(&f.member, &basic, at(2))
            .unwrap()
            .value
            .sequence,
        4
    );
    assert_eq!(last_kind(&f), RtMessageType::Basic);
    assert_eq!(f.count("rt_messages"), 4);
}

#[test]
fn other_kinds_and_malformed_pegged_metadata_are_refused() {
    let (mut f, go) = go_channel();
    let reply = go_send("reply");
    let mut refused = Vec::new();
    // Kinds with no body arm, including the server-authored ones, which
    // go-foks main stores and the Rust server refuses.
    for kind in [
        RtMessageType::None,
        RtMessageType::Delete,
        RtMessageType::Attachment,
        RtMessageType::System,
        RtMessageType::Join,
        RtMessageType::Leave,
    ] {
        let mut arg = reply.clone();
        arg.send.metadata.kind = kind;
        refused.push(arg);
    }
    let mut zero_id = reply.clone();
    zero_id.send.metadata.id = RtMessageId([0; 16]);
    let mut attributed = reply.clone();
    attributed.send.metadata.further_user_attribution =
        Some(RtUserId::new(EntityId::from_bytes(f.member.uid.clone()).unwrap()).unwrap());
    let mut half_predecessor = reply.clone();
    half_predecessor.send.metadata.previous_sequence = 0;
    let mut short = reply.clone();
    let RtMessageWrapper::Encrypted(boxed) = &mut short.send.wrapper else {
        panic!("encrypted")
    };
    boxed.ciphertext.0.truncate(15);
    let mut role = reply.clone();
    let RtMessageWrapper::Encrypted(boxed) = &mut role.send.wrapper else {
        panic!("encrypted")
    };
    boxed.key.role = Role::ADMIN;
    refused.extend([zero_id, attributed, half_predecessor, short, role]);
    for arg in &refused {
        assert!(
            matches!(f.db.rt_send(&go, arg, at(0)), Err(Error::Invalid(_))),
            "{:?}",
            arg.send.metadata.kind
        );
    }
    assert_eq!(f.count("rt_messages"), 1);
    assert_eq!(last_kind(&f), RtMessageType::Basic);
    // The refusals left nothing behind: the fixture send is still fresh.
    assert!(!f.db.rt_send(&go, &reply, at(0)).unwrap().value.was_replay);
}
